vStream.dispatchEvent(new Event('play', { bubbles: true }));
if (ind.style.display === 'none') return false;

const rect = ind.getBoundingClientRect();
if (rect.left < 0 || rect.right > window.innerWidth) return false;
if (rect.top < 0 || rect.bottom > window.innerHeight) return false;

adapter._hide();
return true;

